using UnityEngine;

public class BgmChanger : MonoBehaviour
{
	public string triggerBgmName = string.Empty;

	public bool autoDisable;

	private bool triggered;

	private string targetName = "AllyFloorContact";

	private string targetTag = "Player";

	public void OnTriggerEnter2D(Collider2D col)
	{
		if (!triggered && col.name == targetName && col.gameObject.CompareTag(targetTag))
		{
			triggered = true;
			SoundManager.PlayBGM(triggerBgmName);
			if (autoDisable)
			{
				gameObject.SetActive(value: false);
			}
		}
	}

	public void OnTriggerExit2D(Collider2D col)
	{
		if (triggered && col.name == targetName && col.gameObject.CompareTag(targetTag))
		{
			triggered = false;
		}
	}
