	private bool ClaimInputDevice()
	{
		if (currentController == null)
		{
			return false;
		}
		playerInputDev = InputController.ClaimController(playerID, currentController);
		if (playerInputDev == null)
		{
			currentController = null;
			return false;
		}
		startPromptImage.sprite = GameUI.GetInputSprite(playerInputDev.inputScheme);
		SoundManager.PlayAudio("Equip");
		DisplayJoinPrompt(enable: false);
		return true;
	}

	private void ReleaseInputDevice()
	{
		InputController.ReleaseControllers(playerInputDev);
		playerInputDev = null;
		currentController = null;
		DisplayJoinPrompt();
	}

	private void DisplayJoinPrompt(bool enable = true)
	{
		if (enable)
		{
			inputDeviceClaimed = false;
			joinPromptBG.enabled = true;
			joinPrompt.SetActive(value: true);
			characterSelector.SetActive(value: false);
			joinPromptImage.sprite = GameUI.GetInputSprite(ChaosInputDevice.InputScheme.Gamepad);
		}
		else
		{
			inputDeviceClaimed = true;
			joinPromptBG.enabled = false;
			joinPrompt.SetActive(value: false);
		}
	}

	private void Update()
	{
		if (!activated || LoadingScreen.loading)
		{
			return;
		}
		if (playerInputDev != null && playerInputDev.controllerCount > 0)
		{
			playerInputDev.SetPlayer(player);
			SpawnPlayer();
			Disable();
			return;
		}
		currentController = InputController.GetAnyDeviceButtonDown("Cancel");
		if (currentController != null && !GameController.coopOn && !GameController.pvpOn)
		{
			GameController.LoadLevel("TitleScreen");
			return;
		}
		currentController = InputController.GetAnyDeviceButtonDown("Confirm");
		if (currentController != null)
		{
			ClaimInputDevice();
		}
	}

	public void SpawnPlayer()
	{
		player = Player.Spawn(playerInputDev);
		player.AssignPlayerID(playerID);
		Player.UpdateActivePlayers();
		SoundManager.PlayAudio("Equip");
		if (player.playerID == 0)
		{
			GameController.p1Joined = true;
		}
		else
		{
			GameController.p2Joined = true;
		}
		if ((GameController.p1Joined || GameController.p2Joined) && !player.TeleportToPartner(-1, showSpawnPortal: true, excludeOrigin: true))
		{
			player.TeleportToPartner(-1, showSpawnPortal: true, excludeOrigin: true);
			PoolManager.GetPoolItem<AnimEffect>("TeleportEffect").Play(player.transform.position, string.Empty);
		}
	}

	public void Activate()
	{
		DisplayJoinPrompt(playerInputDev == null);
		gameObject.SetActive(value: true);
		activated = true;
	}

	public void Disable(bool releaseInputDevice = false)
	{
		if (releaseInputDevice)
		{
			ReleaseInputDevice();
		}
		gameObject.SetActive(value: false);
		activated = false;
	}
