private void RefreshFields()
{
	cmRef.mouseAimFill.enabled = ChaosInputDevice.allowMouseAim;
	cmRef.mouseDashFill.enabled = ChaosInputDevice.allowMouseDash;
	foreach (KeyValuePair<CInput, Text> item in cmRef.fieldValueDict)
	{
		if (!(item.Value == null) && inputToHandleDict.ContainsKey(item.Key))
		{
			if (item.Key.ToString().Contains("Move"))
			{
				item.Value.text = InputMapHelper.GetActionElementName(InputToActionName[item.Key], useAxis: true, item.Key == CInput.MoveUp || item.Key == CInput.MoveRight);
			}
			else
			{
				item.Value.text = InputMapHelper.GetActionElementName(InputToActionName[item.Key]);
			}
		}
	}
}

private bool InputKeyRecorded(CInput givenInput)
{
	if (Input.anyKeyDown)
	{
		KeyCode[] array = KeyCodeValues;
		for (int i = 0; i < array.Length; i++)
		{
			KeyCode keyCode = array[i];
			if (keyCode != KeyCode.Escape && keyCode != KeyCode.Return && !keyCode.ToString().Contains("Joystick") && Input.GetKeyDown(keyCode))
			{
				AssignKeyToInput(givenInput, keyCode);
				SoundManager.PlayConfirmAudio();
				return true;
			}
		}
	}
	return false;
}

private void AssignKeyToInput(CInput givenInput, KeyCode givenKey)
{
	InputMapHelper.CreateElementMapForAll(InputToActionName[givenInput], givenKey, (givenInput == CInput.MoveDown || givenInput == CInput.MoveLeft) ? Pole.Negative : Pole.Positive);
}

private void RequestConfirm()
{
	inConfirmWindow = true;
	cmRef.confirmationWindow.SetActive(value: true);
