	private float prevHealth;
	private float changingHealth;
	private bool isHealthChanging;
	private float healthUpdateDelayTime = 1.5f;

	private void Reset()
	{
		player = null;
		isHealthChanging = false;
		changingHealth = 0f;
		currentHealth = 0f;
		prevHealth = 0f;
		if (itemStatusBar != null)
		{
			itemStatusBar.playerID = -1;
		}
	}

	private void Update()
	{
		if (player == null)
		{
			if (gameObject.activeSelf)
			{
				Release();
			}
		}
		else
		{
			HandleHealth();
			HandleOverdrive();
		}
	}

	private void HandleHealth()
	{
		currentHealth = player.health.healthStat.CurrentValue;
		if (currentHealth < prevHealth)
		{
			if (ChaosStopwatch.Check(healthDelayStopwatchID))
			{
				changingHealth = prevHealth;
			}
			healthDelayStopwatchID = ChaosStopwatch.Begin(healthUpdateDelayTime);
		}
		changingHealth -= ((!(changingHealth > currentHealth)) ? 0f : (Time.deltaTime * 25f));
		prevHealth = currentHealth;
		HPBarFill.fillAmount = player.health.HealthPercentage;
		HPBarHurtFill.fillAmount = changingHealth / player.health.healthStat.ModifiedValue;
		HPText.text = (int)currentHealth/*cast due to constrained. prefix*/ + "/" + (int)player.health.healthStat.ModifiedValue/*cast due to constrained. prefix*/;
		if (HPBarFill.fillAmount <= healthBlinkThreshold && HPBarFill.fillAmount != 0f)
		{
			blinkSpeed = Mathf.Max(healthBlinkThreshold - HPBarFill.fillAmount, 0.1f) * 22f;
			if (healthColorLerpValue >= 1f)
			{
				healthLerpDown = true;
			}
			if (healthColorLerpValue <= 0f)
			{
				healthLerpDown = false;
			}
			healthColorLerpValue += blinkSpeed * Time.deltaTime * (float)((!healthLerpDown) ? 1 : (-1));
			statusBarBG.color = Color.Lerp(Color.white, Color.red, healthColorLerpValue);
			playerPortrait.color = statusBarBG.color;
			if (!healthLowAudioPlayed && !LoadingScreen.loading)
			{
				healthLowAudioPlayed = true;
				SoundManager.PlayAudio("HealthLow");
			}
		}
		else
		{
			statusBarBG.color = Color.white;
			playerPortrait.color = Color.white;
			healthLowAudioPlayed = false;
		}
	}

	private void HandleOverdrive()
	{
		float overdrivePercentage = player.OverdrivePercentage;
		overdriveBarFill.fillAmount = overdrivePercentage;
		if (player.overdriveReady)
		{
			overdriveBarFill.color = overdriveFadeColor;
			if (overdriveFadeColor.a >= 1f)
			{
				overdriveFadeOut = true;
			}
			else if (overdriveFadeColor.a <= 0.4f)
			{
				overdriveFadeOut = false;
			}
			overdriveFadeColor.a += Time.deltaTime * 2.5f * (float)((!overdriveFadeOut) ? 1 : (-1));
		}
		else
		{
			overdriveFadeColor.a = 1f;
			overdriveBarFill.color = Color.white;
		}
		playerShieldBar = base.transform.Find("PlayerShieldBar").GetComponent<Image>();
		playerShieldBarBG = base.transform.Find("PlayerShieldBarBG").GetComponent<Image>();
		playerShieldBar.enabled = false;
		playerShieldBarBG.enabled = false;
	}

	private void Start()
	{
		playerScript = parentPlayer.GetComponent<Player>();
		playerHealth = playerScript.health;
		if (castBar == null)
		{
			castBar = Globals.ChaosInst<CastBar>(CastBar.Prefab, transform.parent, transform.position);
			castBar.parentTrans = parentPlayer.transform;
			castBar.SetBarDimensions(0.44f, 0.56f, 0.7f, 0.71f);
			castBar.GetComponent<Canvas>().overrideSorting = true;
		}
		respawnImage.GetComponent<Image>().sprite = ((!playerScript.IsKeyboardInput) ? GameUI.UIButtonIcons["GamepadButtonGreen"] : GameUI.KeyboardKeyIcons["Space"]);
	}

	private void Update()
	{
		transform.position = playerScript.hurtBoxTransform.position;
		HandleShieldBar();
	}

