	private void HandleShieldBar()
	{
		if (playerHealth.CurrentShieldValue <= 0)
		{
			playerShieldBar.enabled = false;
			playerShieldBarBG.enabled = false;
		}
		else
		{
			playerShieldBar.enabled = true;
			playerShieldBarBG.enabled = true;
			playerShieldBar.fillAmount = playerHealth.ShieldPercentage;
		}
	}
